<?php declare(strict_types=1);
use Kulturhus\Verein\{MemberCards,MemberCardWallet};
use Kulturhus\Verein\Web\{MemberCardForm,MemberCardPage,MemberCardWalletPage};
use Kulturhus\Native\Language\{MemberCardMessages,ManagerMessages};

(static function(PDO $db,\Kulturhus\Native\Shared\SecretBox $box,\Closure $clock,callable $check):void{
    $service=new MemberCards($db,'own-card-member',$box,$clock);$context=MemberCardForm::prepare($service,'member-one');$card=$service->card('member-one',$context['state']['head']['card_id']);$history=$service->history('member-one');$tables=$db->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN);$before=ownOriginalDatabaseHash($db,$tables);parse_str((string)parse_url($card['verify_url'],PHP_URL_QUERY),$qr);
    foreach(['de','en']as$locale){$messages=ManagerMessages::messages($locale);$page=new MemberCardPage('own-card-csrf',$messages,$locale);$html=$page->render($context,$card,$history,['apple'=>false,'google'=>false]);
        $check(str_contains($html,$locale==='de'?'Ausweis erneuern':'Renew card')&&str_contains($html,'Eigene Person member-one'),'actual card page has translated human controls and the exact original owner');
        $check(str_contains($html,'member-card-face')&&str_contains($html,'card_asset=qr')&&!str_contains($html,$qr['token']),'actual card HTML uses the authenticated PNG endpoint without exposing the raw verification token');
        $check(!str_contains($html,'href="/?')&&!str_contains($html,'Angezeigte Fassung'),'actual card navigation stays in the deployed manager directory without technical revision text');
        $bad=['action'=>'member-card-issue','contact_id'=>'member-one','version'=>(string)$context['state']['version'],'source_hash'=>$context['state']['source']['fingerprint'],'request_id'=>bin2hex(random_bytes(16)),'valid_until'=>'oops','public_name'=>'0'];$draft=MemberCardForm::prepare($service,'member-one',$bad);$html=$page->render($draft,$card,$history,[], 'Ausweisangaben erneut prüfen.');$check(str_contains($html,'value="oops"')&&str_contains($html,'name="request_id" value="'.$bad['request_id'].'"'),'actual refused form retains correctable human input and the original command identity');
        $recovery=$page->recovery('member-one',$bad,'Mitgliederausweis wird gerade bearbeitet. Deine Angaben bleiben erhalten.');$check(str_contains($recovery,'value="oops"')&&str_contains($recovery,$bad['source_hash'])&&str_contains($recovery,'member-card-recheck'),'unavailable original read has a deliberate read-only recheck with the same original metadata');
    }
    $check(ownOriginalDatabaseHash($db,$tables)===$before,'all card form preparation rendering and recovery leave every whole original exact');
    $request=$db->prepare("SELECT request_id,result_json FROM member_card_commands WHERE club_id='own-card-club' AND actor_id='own-card-member' AND operation='issue' AND card_id<>? LIMIT 1");$request->execute([$card['id']]);$prior=$request->fetch();$old=json_decode($prior['result_json'],true,32,JSON_THROW_ON_ERROR)['result'];
    $changed=['action'=>'member-card-issue','contact_id'=>'member-one','request_id'=>$prior['request_id'],'version'=>[],'source_hash'=>[],'valid_until'=>'changed invalid original','public_name'=>[]];$r=MemberCardForm::act($service,'member-one',['view'=>'portal','tab'=>'card','person'=>'member-one'],$changed);$check($r['reused']&&$r['result']===$old&&ownOriginalDatabaseHash($db,$tables)===$before,'actual form replay returns its original saved operation before adopting any changed human or hidden argument');
    $guardCalls=0;$guard=static function()use(&$guardCalls):void{if(++$guardCalls===2)throw new DomainException('Own actual authentication revocation');};$guarded=new MemberCards($db,'own-card-member',$box,$clock,$guard);$post=['action'=>'member-card-issue','contact_id'=>'member-one','version'=>(string)$context['state']['version'],'source_hash'=>$context['state']['source']['fingerprint'],'request_id'=>bin2hex(random_bytes(16)),'valid_until'=>'2026-11-30','public_name'=>'1'];
    try{MemberCardForm::prepare($guarded,'member-one',$post);throw new RuntimeException('Authentication failure was swallowed');}catch(DomainException $e){$check($e->getCode()===403,'current account refusal during form preparation cannot be downgraded into a stale editable form');}
