        public bool $loseCommit=false;public string $targetRequest='';public function commit():bool{$r=parent::commit();if($this->loseCommit){$q=$this->prepare("SELECT 1 FROM member_card_commands WHERE club_id='own-card-club' AND request_id=?");$q->execute([$this->targetRequest]);if($q->fetchColumn()){$this->loseCommit=false;throw new PDOException('Own synthetic lost COMMIT acknowledgement');}}return$r;}
    };
    $family=new MemberCards($connection,'own-card-family',$box,$clock);$s=MemberCardForm::prepare($family,'member-two');$post=['action'=>'member-card-issue','contact_id'=>'member-two','version'=>'0','source_hash'=>$s['state']['source']['fingerprint'],'request_id'=>bin2hex(random_bytes(16)),'valid_until'=>'2027-10-30','public_name'=>'1'];$frame=['view'=>'portal','tab'=>'card','person'=>'member-two'];$connection->targetRequest=$post['request_id'];$connection->loseCommit=true;
    try{MemberCardForm::act($family,'member-two',$frame,$post);throw new RuntimeException('Own lost acknowledgement did not occur');}catch(PDOException){$check(!$connection->inTransaction(),'real MySQL COMMIT completes before its synthetic acknowledgement is lost');}
    $afterCommit=ownOriginalDatabaseHash($db,$tables);$prepared=MemberCardForm::prepare($family,'member-two',$post);$check($prepared['saved']!==null&&$prepared['issue']['version']==='0'&&$prepared['issue']['request_id']===$post['request_id'],'lost COMMIT response is recovered by the actual saved command while the original form version remains untouched');
    $r=MemberCardForm::act($family,'member-two',$frame,array_replace($post,['valid_until'=>'invalid date','public_name'=>'0']));$check($r['reused']&&$r['result']===$prepared['saved']&&ownOriginalDatabaseHash($db,$tables)===$afterCommit,'changed form retry after a real accepted COMMIT creates no duplicate card command or audit');
    $meta=(new MemberCardWallet($db,'own-card-admin',$box,$clock))->state();$publicPost=['action'=>'member-card-wallet-apple','wallet_version'=>(string)$meta['apple']['version'],'enabled'=>'1','pass_type_id'=>'pass.invalid.retained','team_id'=>'TEAM123456','apple_password'=>'own private password never rendered'];
    foreach(['de','en']as$locale){$html=(new MemberCardWalletPage('own-card-csrf',ManagerMessages::messages($locale)))->render($meta,$publicPost,'Apple-Zertifikat oder dessen Passwort prüfen.');$check(str_contains($html,'value="pass.invalid.retained"')&&str_contains($html,'value="TEAM123456"')&&!str_contains($html,$publicPost['apple_password']),'actual wallet refusal retains public identifiers and never reflects the certificate password');}
